export function chainFrame(x=.5,skip=false,stage=8){if(!Number.isFinite(x)||Math.abs(x)>2||!Number.isInteger(stage)||stage<0||stage>8)throw new Error('Invalid graph state');const a=x*x,b=Math.sin(a),c=Math.exp(b),loss=c+(skip?a:0),values=[x,a,b,c,loss],ready=[true,stage>=1,stage>=2,stage>=3,stage>=4],adjoints=[stage>=8?2*x*(c*Math.cos(a)+(skip?1:0)):0,stage>=7?c*Math.cos(a)+(skip?1:0):stage>=5&&skip?1:0,stage>=6?c:0,stage>=5?1:0,stage>=4?1:0];return {values,ready,adjoints,derivative:2*x*(c*Math.cos(a)+(skip?1:0)),stage,skip};}
export function partialExample(x,y){if(![x,y].every(Number.isFinite))throw new Error('Invalid point');return {value:x*x*y+x*y*y,gradient:[2*x*y+y*y,x*x+2*x*y],hessian:[[2*y,2*x+2*y],[2*x+2*y,2*x]]};}
export const curvatureProfiles={minimum:{eigen:[1,3],label:'Positive definite'},saddle:{eigen:[1,-1],label:'Indefinite'},maximum:{eigen:[-1,-3],label:'Negative definite'},quartic:{eigen:[0,0],label:'Degenerate quartic'}};
export function curvatureFrame(kind,degrees,r=1){const p=curvatureProfiles[kind];if(!p||![degrees,r].every(Number.isFinite))throw new Error('Invalid curvature state');const t=degrees*Math.PI/180,direction=[Math.cos(t),Math.sin(t)],k=p.eigen[0]*direction[0]**2+p.eigen[1]*direction[1]**2,value=kind==='quartic'?r**4*(direction[0]**4+direction[1]**4):.5*k*r*r;return {direction,k,value,eigen:p.eigen,label:p.label,kind};}
export function classifyEigenvalues(eigen){if(!eigen.length||eigen.some(v=>!Number.isFinite(v)))throw new Error('Invalid eigenvalues');const index=eigen.filter(v=>v<0).length,zeros=eigen.filter(v=>v===0).length;return {index,zeros,type:index>0&&index+zeros<eigen.length?'Saddle':zeros?'Degenerate; second-order test incomplete':index===0?'Minimum':'Maximum'};}
